### ① Concept Explanation

**Hallucinated arguments** occur when the LLM calls a tool with fabricated parameter values — URLs that don't exist, user IDs that were never mentioned, dates from a different context, or function names that weren't defined. This is especially dangerous for tools with side effects (sending emails, making payments, deleting data). Defense requires three layers: schema validation (Pydantic catches type/format errors), semantic validation (check that argument values are grounded in the conversation context), and allowlist validation (for critical tools, verify values against known-good sets).

```python
import re
from pydantic import BaseModel, field_validator
import json

# ── Schema validation with Pydantic ───────────────────────────
class PaymentToolArgs(BaseModel):
    """Strict argument schema for payment tool — prevents hallucinated values."""
    recipient_id: str
    amount_usd: float
    currency: str
    description: str

    @field_validator("amount_usd")
    @classmethod
    def validate_amount(cls, v: float) -> float:
        if v <= 0:
            raise ValueError(f"Amount must be positive, got {v}")
        if v > 10_000:
            raise ValueError(f"Amount {v} exceeds max ($10,000) — requires manual approval")
        return v

    @field_validator("currency")
    @classmethod
    def validate_currency(cls, v: str) -> str:
        allowed = {"USD", "EUR", "GBP", "JPY"}
        if v.upper() not in allowed:
            raise ValueError(f"Currency {v!r} not in allowed set {allowed}")
        return v.upper()

    @field_validator("recipient_id")
    @classmethod
    def validate_recipient_format(cls, v: str) -> str:
        # Recipient IDs must match format "usr_<alphanum>"
        if not re.match(r"^usr_[a-zA-Z0-9]{8,}$", v):
            raise ValueError(f"Invalid recipient_id format: {v!r} — must be 'usr_<alphanum>'")
        return v

# ── Grounding validation (context-aware) ──────────────────────
class GroundingValidator:
    """
    Validate that tool arguments are grounded in conversation context.
    Prevents hallucinated values that were never mentioned by the user.
    """
    def __init__(self, context_window: int = 2000):
        self.context_window = context_window
        self._conversation_text: str = ""

    def update_context(self, messages: list[dict]) -> None:
        """Extract plaintext from conversation for grounding checks."""
        texts = []
        for msg in messages:
            if isinstance(msg.get("content"), str):
                texts.append(msg["content"])
        self._conversation_text = " ".join(texts)[-self.context_window:]

    def is_grounded(self, value: str) -> bool:
        """
        Check if a value appears (or was derivable) from conversation.
        Simple substring check — production would use NER + fuzzy match.
        """
        return str(value).lower() in self._conversation_text.lower()

    def validate_payment_args(
        self,
        args: PaymentToolArgs,
        messages: list[dict],
    ) -> list[str]:
        """Return list of grounding violations."""
        self.update_context(messages)
        violations = []

        if not self.is_grounded(args.recipient_id):
            violations.append(
                f"recipient_id {args.recipient_id!r} not found in conversation context — "
                "possible hallucination"
            )

        if not self.is_grounded(str(args.amount_usd)):
            violations.append(
                f"amount ${args.amount_usd} not found in conversation — "
                "LLM may have fabricated this value"
            )

        return violations

# ── Full argument validation pipeline ─────────────────────────
async def safe_payment_tool(
    raw_args: str,
    messages: list[dict],
    grounding_validator: GroundingValidator,
) -> str:
    """
    Execute payment tool with full argument validation.
    Never executes with hallucinated arguments.
    """
    # Step 1: Parse JSON
    try:
        args_dict = json.loads(raw_args)
    except json.JSONDecodeError as e:
        return f"ERROR: Invalid JSON arguments: {e}"

    # Step 2: Schema validation
    try:
        args = PaymentToolArgs(**args_dict)
    except Exception as e:
        logger.error(f"Schema validation failed: {e}")
        return f"ERROR: Invalid arguments — {e}"

    # Step 3: Grounding validation
    violations = grounding_validator.validate_payment_args(args, messages)
    if violations:
        logger.error(f"Grounding violations detected: {violations}")
        return (
            f"BLOCKED: Potential hallucinated arguments detected:\n"
            + "\n".join(f"  - {v}" for v in violations)
            + "\nPlease confirm these values with the user before proceeding."
        )

    # Step 4: Safe to execute
    logger.info(f"Payment validated and executing: ${args.amount_usd} to {args.recipient_id}")
    return f"Payment of ${args.amount_usd} to {args.recipient_id} — SIMULATED SUCCESS"
